// Generates the "loam" logo suite as hand-tuned, dependency-free SVG.
// Usage: node src/build.mjs   (writes SVGs to ./output)
import { writeFileSync, mkdirSync } from "node:fs";

const OUT = new URL("../output/", import.meta.url);
mkdirSync(OUT, { recursive: true });

// Neutral, earth-derived palette
const C = {
  bone: "#F3EEE6",
  oat: "#E4D9C8",
  sand: "#CDBA9F",
  clay: "#AE8E71",
  umber: "#7C624D",
  bark: "#4A3D33",
  char: "#2B2622",
  stone: "#8F877D",
};

const f = (n) => +n.toFixed(2);

// Closed Catmull-Rom spline -> cubic Bézier path
function smoothClosed(pts) {
  const n = pts.length;
  const P = (i) => pts[(i + n) % n];
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`;
  for (let i = 0; i < n; i++) {
    const p0 = P(i - 1), p1 = P(i), p2 = P(i + 1), p3 = P(i + 2);
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${f(c1[0])} ${f(c1[1])} ${f(c2[0])} ${f(c2[1])} ${f(p2[0])} ${f(p2[1])}`;
  }
  return d + "Z";
}

// An organic pebble outline: low-frequency harmonics on a circle
function pebble({ cx, cy, r, twist = 0, amp = 1, n = 14 }) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const t = (i / n) * Math.PI * 2;
    const k =
      1 +
      amp *
        (0.075 * Math.cos(2 * (t - 0.62 - twist)) +
          0.035 * Math.sin(3 * t + 1.1 + twist * 1.6) +
          0.012 * Math.cos(5 * t + 0.4 - twist));
    pts.push([cx + Math.cos(t) * r * k, cy + Math.sin(t) * r * k]);
  }
  return smoothClosed(pts);
}

// The mark: nested strata, like a river stone cut open or growth rings
// drifting toward a single light seed. Drawn in a 240×240 box.
function markLayers(palette) {
  const rings = [
    { r: 108, fill: palette[0] },
    { r: 86, fill: palette[1] },
    { r: 65, fill: palette[2] },
    { r: 45, fill: palette[3] },
    { r: 27, fill: palette[4] },
  ];
  const drift = [17, -15]; // strata drift toward upper-right: the growth front
  const out = rings.map((ring, k) => {
    const t = Math.pow(k / (rings.length - 1), 1.15);
    return `<path fill="${ring.fill}" d="${pebble({
      cx: 120 + drift[0] * t,
      cy: 122 + drift[1] * t,
      r: ring.r,
      twist: k * 0.2,
      amp: 1 - k * 0.1,
    })}"/>`;
  });
  // seed / spark
  out.push(
    `<path fill="${palette[5]}" d="${pebble({ cx: 140, cy: 105, r: 9.5, twist: 1.3, amp: 1.4, n: 8 })}"/>`
  );
  return out.join("");
}

const LIGHT = [C.oat, C.sand, C.clay, C.umber, C.char, C.bone];
const DARK = [C.bark, C.umber, C.clay, C.sand, C.bone, C.char];

// Custom monoline wordmark "loam" (round caps, soft terminals).
// Units: baseline y=0, x-height 1. Returns path data in given scale/origin.
function wordmark(x0, base, xh, sw) {
  const s = (v) => f(v * xh);
  const X = (v) => f(x0 + v * xh);
  const Y = (v) => f(base - v * xh);
  const r = 0.5 - sw / xh / 2; // bowl radius in units, centred on stroke
  const parts = [];
  let x = 0;

  // l — tall stem with a soft rolled foot
  const lx = x + sw / xh / 2;
  parts.push(
    `M${X(lx)} ${Y(1.52)}V${Y(0.22)}Q${X(lx)} ${Y(0)} ${X(lx + 0.2)} ${Y(0)}`
  );
  x = lx + 0.2 + 0.2;

  // o — a gently irregular bowl, echoing the pebble
  const ocx = x + r + sw / xh / 2;
  {
    const pts = [];
    const n = 12;
    for (let i = 0; i < n; i++) {
      const t = (i / n) * Math.PI * 2;
      const k = 1 + 0.035 * Math.cos(2 * (t - 0.62)) + 0.015 * Math.sin(3 * t + 1.1);
      pts.push([x0 + (ocx + Math.cos(t) * r * k * 1.02) * xh, base - (0.5 + Math.sin(t) * r * k) * xh]);
    }
    parts.push(smoothClosed(pts).replace(/Z$/, "Z"));
  }
  x = ocx + r + sw / xh / 2 + 0.17;

  // a — single-storey: bowl + stem
  const acx = x + r + sw / xh / 2;
  parts.push(
    `M${X(acx + r)} ${Y(0.5)}A${s(r)} ${s(r)} 0 1 0 ${X(acx - r)} ${Y(0.5)}A${s(r)} ${s(r)} 0 1 0 ${X(acx + r)} ${Y(0.5)}Z`
  );
  parts.push(`M${X(acx + r)} ${Y(1 - sw / xh / 2)}V${Y(sw / xh / 2)}`);
  x = acx + r + sw / xh / 2 + 0.19;

  // m — stem and two rounded arches
  const mr = 0.27;
  const m0 = x + sw / xh / 2;
  const top = 1 - sw / xh / 2;
  const bot = sw / xh / 2;
  parts.push(`M${X(m0)} ${Y(top)}V${Y(bot)}`);
  parts.push(
    `M${X(m0)} ${Y(top - mr)}A${s(mr)} ${s(mr)} 0 0 1 ${X(m0 + 2 * mr)} ${Y(top - mr)}V${Y(bot)}`
  );
  parts.push(
    `M${X(m0 + 2 * mr)} ${Y(top - mr)}A${s(mr)} ${s(mr)} 0 0 1 ${X(m0 + 4 * mr)} ${Y(top - mr)}V${Y(bot)}`
  );
  x = m0 + 4 * mr + sw / xh / 2;

  return { d: parts.join(""), width: x * xh };
}

function svg(w, h, body, title) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${title}"><title>${title}</title>${body}</svg>\n`;
}

function lockup({ bg, palette, ink, sub }) {
  const W = 760, H = 300;
  const mx = 50, my = 30, ms = 1; // mark at 240px
  const xh = 92, sw = 15;
  const base = my + 120 + xh * 0.5;
  const wm = wordmark(mx + 240 + 46, base, xh, sw);
  let body = bg ? `<rect width="${W}" height="${H}" fill="${bg}"/>` : "";
  body += `<g transform="translate(${mx} ${my}) scale(${ms})">${markLayers(palette)}</g>`;
  body += `<path d="${wm.d}" fill="none" stroke="${ink}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"/>`;
  return { svg: svg(W, H, body, "loam — generative intelligence"), wmWidth: wm.width };
}

const files = {
  "loam-logo-light.svg": lockup({ bg: C.bone, palette: LIGHT, ink: C.char }),
  "loam-logo-dark.svg": lockup({ bg: C.char, palette: DARK, ink: C.bone }),
};

for (const [name, v] of Object.entries(files)) {
  writeFileSync(new URL(name, OUT), v.svg);
  console.log(name, "wordmark width", Math.round(v.wmWidth));
}

writeFileSync(
  new URL("loam-mark.svg", OUT),
  svg(240, 240, markLayers(LIGHT), "loam mark")
);
console.log("loam-mark.svg");

